CREATE TABLE public.secoes_home (
  secao text PRIMARY KEY,
  ordem integer NOT NULL DEFAULT 0,
  conteudo_pt jsonb NOT NULL DEFAULT '{}'::jsonb,
  conteudo_es jsonb NOT NULL DEFAULT '{}'::jsonb,
  atualizado_em timestamptz NOT NULL DEFAULT now()
);
GRANT SELECT ON public.secoes_home TO anon;
GRANT SELECT, INSERT, UPDATE ON public.secoes_home TO authenticated;
GRANT ALL ON public.secoes_home TO service_role;
ALTER TABLE public.secoes_home ENABLE ROW LEVEL SECURITY;
CREATE POLICY "public read secoes_home" ON public.secoes_home FOR SELECT TO anon, authenticated USING (true);
CREATE POLICY "staff insert secoes_home" ON public.secoes_home FOR INSERT TO authenticated WITH CHECK (private.can_edit_content(auth.uid()));
CREATE POLICY "staff update secoes_home" ON public.secoes_home FOR UPDATE TO authenticated USING (private.can_edit_content(auth.uid())) WITH CHECK (private.can_edit_content(auth.uid()));
CREATE TRIGGER secoes_home_touch BEFORE UPDATE ON public.secoes_home FOR EACH ROW EXECUTE FUNCTION public.touch_atualizado();

INSERT INTO public.secoes_home (secao, ordem, conteudo_pt, conteudo_es) VALUES
('hero', 0, '{"eyebrow":"Freio pneumático para implementos · fabricação própria","titulo":"Não importa o caminho, vá com Fluair!","subtitulo":"Há mais de 25 anos fabricamos as válvulas e os kits ABS que compõem o sistema de freio de reboques, semirreboques e trucks.","cta_primario_label":"Ver produtos","cta_primario_url":"/produtos","cta_secundario_label":"Falar com a gente","scroll":"Role"}'::jsonb, '{"eyebrow":"Freno neumático para implementos · fabricación propia","titulo":"No importa el camino, ¡ve con Fluair!","subtitulo":"Hace más de 25 años fabricamos las válvulas y los kits ABS que componen el sistema de freno de remolques, semirremolques y camiones.","cta_primario_label":"Ver productos","cta_secundario_label":"Hablar con nosotros","scroll":"Desliza"}'::jsonb),
('numeros', 1, '{"itens":[{"valor":"","rotulo":"Itens em linha","auto":"produtos"},{"valor":"+25","rotulo":"Anos de fabricação","auto":""},{"valor":"","rotulo":"Categorias de produto","auto":"categorias"},{"valor":"ISO","rotulo":"Qualidade 9001:2015","auto":""}]}'::jsonb, '{"itens":[{"rotulo":"Ítems en línea"},{"rotulo":"Años de fabricación"},{"rotulo":"Categorías de producto"},{"rotulo":"Calidad 9001:2015"}]}'::jsonb),
('sistema', 2, '{"kick":"O sistema","titulo":"Tudo que freia o seu implemento","texto":"Do engate à válvula relê, a Fluair fabrica os componentes do sistema de freio pneumático — pensados para trabalhar juntos.","contador_texto":"componentes em linha, prontos para especificar","itens":[{"titulo":"Engate de serviço e emergência","texto":"Conexão pneumática entre o cavalo e o implemento.","tag":"Automático / Manual"},{"titulo":"Filtro de rede","texto":"Protege o circuito contra impurezas do ar comprimido.","tag":"Componentes"},{"titulo":"Válvula moduladora (ABS)","texto":"Modula a pressão de freio no eixo — base do ABS Fluair.","tag":"Linha ABS"},{"titulo":"Painel de comando","texto":"Concentra o comando pneumático do implemento.","tag":"Painéis de Comando"},{"titulo":"Válvula relê","texto":"Acelera o acionamento levando ar direto ao ponto de atuação.","tag":"Válvulas"},{"titulo":"Descarga rápida","texto":"Libera rapidamente o ar das câmaras no desacionamento.","tag":"Válvulas"},{"titulo":"Dupla retenção","texto":"Garante prioridade e segurança entre os circuitos de ar.","tag":"Válvulas"}]}'::jsonb, '{"kick":"El sistema","titulo":"Todo lo que frena su implemento","texto":"Del acople a la válvula relé, Fluair fabrica los componentes del sistema de freno neumático — pensados para trabajar juntos.","contador_texto":"componentes en línea, listos para especificar","itens":[{"titulo":"Acople de servicio y emergencia","texto":"Conexión neumática entre el tractor y el implemento.","tag":"Automático / Manual"},{"titulo":"Filtro de línea","texto":"Protege el circuito contra impurezas del aire comprimido.","tag":"Componentes"},{"titulo":"Válvula moduladora (ABS)","texto":"Modula la presión de freno en el eje — base del ABS Fluair.","tag":"Línea ABS"},{"titulo":"Panel de comando","texto":"Concentra el comando neumático del implemento.","tag":"Paneles de Comando"},{"titulo":"Válvula relé","texto":"Acelera el accionamiento llevando aire directo al punto de actuación.","tag":"Válvulas"},{"titulo":"Descarga rápida","texto":"Libera rápidamente el aire de las cámaras al desaccionar.","tag":"Válvulas"},{"titulo":"Doble retención","texto":"Garantiza prioridad y seguridad entre los circuitos de aire.","tag":"Válvulas"}]}'::jsonb),
('categorias', 3, '{"kick":"Catálogo","titulo":"{n} linhas,","destaque":"um sistema","texto":"Da Linha ABS às válvulas, painéis, conexões, manômetros, reparos e tubos.","link_label":"Ver produtos →"}'::jsonb, '{"kick":"Catálogo","titulo":"{n} líneas,","destaque":"un sistema","texto":"De la Línea ABS a las válvulas, paneles, conexiones, manómetros, reparaciones y tubos.","link_label":"Ver productos →"}'::jsonb),
('produtos', 4, '{"kick":"Produtos","titulo":"Alguns itens","destaque":"em linha","texto":"Uma amostra do catálogo — clique para abrir a ficha.","botao_label":"Ver catálogo completo"}'::jsonb, '{"kick":"Productos","titulo":"Algunos ítems","destaque":"en línea","texto":"Una muestra del catálogo — haga clic para abrir la ficha.","botao_label":"Ver catálogo completo"}'::jsonb),
('sobre', 5, '{"kick":"A Fluair","titulo":"Mais de 25 anos","destaque":"na mesma estrada","texto":"Fabricamos válvulas e kits ABS para o sistema de freio de implementos rodoviários, com engenharia própria — fornecedor das grandes montadoras de implementos da América do Sul e da reposição.","fato1":"Certificação ISO 9001:2015","fato3":"Montadoras de implementos da América do Sul","selo1":"ISO","selo2":"9001:2015"}'::jsonb, '{"kick":"Fluair","titulo":"Más de 25 años","destaque":"en la misma ruta","texto":"Fabricamos válvulas y kits ABS para el sistema de freno de implementos viales, con ingeniería propia — proveedor de las grandes montadoras de implementos de América del Sur y del mercado de reposición.","fato1":"Certificación ISO 9001:2015","fato3":"Montadoras de implementos de América del Sur"}'::jsonb),
('porque', 6, '{"kick":"Por que Fluair","titulo":"Quatro motivos","destaque":"para seguir junto","itens":[{"titulo":"Fabricação própria","texto":"Engenharia e produção nacional das válvulas e kits ABS, do projeto à expedição."},{"titulo":"Qualidade ISO 9001:2015","texto":"Processos certificados — o respeito pelo cliente é um compromisso de ordem ética."},{"titulo":"Montadoras da América do Sul","texto":"Fornecedor das grandes montadoras de implementos e de uma ampla rede de reposição."},{"titulo":"Perto de você","texto":"Atendimento em português e espanhol, com suporte e treinamento para a rede."}]}'::jsonb, '{"kick":"Por qué Fluair","titulo":"Cuatro motivos","destaque":"para seguir juntos","itens":[{"titulo":"Fabricación propia","texto":"Ingeniería y producción nacional de las válvulas y kits ABS, del proyecto a la expedición."},{"titulo":"Calidad ISO 9001:2015","texto":"Procesos certificados — el respeto por el cliente es un compromiso ético."},{"titulo":"Montadoras de América del Sur","texto":"Proveedor de las grandes montadoras de implementos y de una amplia red de reposición."},{"titulo":"Cerca de usted","texto":"Atención en portugués y español, con soporte y capacitación para la red."}]}'::jsonb),
('suporte', 7, '{"kick":"Suporte","titulo":"Downloads e","destaque":"atendimento","texto":"","cta_label":"","cta_url":"/suporte","itens":[{"titulo":"Catálogo & Downloads","texto":"Catálogo completo e fichas técnicas.","url":"/downloads"},{"titulo":"Gestão da Qualidade","texto":"ISO 9001:2015 e nossos processos.","url":"/empresa/gestao-da-qualidade"},{"titulo":"F.A.Q & Treinamento","texto":"Dúvidas frequentes e capacitação.","url":"/suporte"},{"titulo":"Onde encontrar","texto":"Rede autorizada e representantes.","url":"/representantes"}]}'::jsonb, '{"kick":"Soporte","titulo":"Descargas y","destaque":"atención","texto":"","cta_label":"","itens":[{"titulo":"Catálogo & Descargas","texto":"Catálogo completo y fichas técnicas."},{"titulo":"Gestión de la Calidad","texto":"ISO 9001:2015 y nuestros procesos."},{"titulo":"F.A.Q & Capacitación","texto":"Preguntas frecuentes y capacitación."},{"titulo":"Dónde encontrar","texto":"Red autorizada y representantes."}]}'::jsonb),
('cta', 8, '{"titulo":"Vamos junto pela estrada?","texto":"Fale com o nosso time comercial e especifique o freio do seu implemento com quem fabrica.","cta_primario_label":"Solicitar orçamento","cta_primario_url":"/orcamento","cta_secundario_label":"WhatsApp"}'::jsonb, '{"titulo":"¿Vamos juntos por la ruta?","texto":"Hable con nuestro equipo comercial y especifique el freno de su implemento con quien lo fabrica.","cta_primario_label":"Solicitar cotización","cta_secundario_label":"WhatsApp"}'::jsonb)
